#include <vector>
#include <algorithm>

class Solution {
public:
    long long maxProduct(std::vector<int>& nums, int m) {
        int n = nums.size();
        if (n < m) return 0;

        long long pref_min = 1e18;
        long long pref_max = -1e18;
        long long best = -1e18;

        for (int j = m - 1; j < n; ++j) {
            int i = j - (m - 1);
            pref_min = std::min(pref_min, (long long)nums[i]);
            pref_max = std::max(pref_max, (long long)nums[i]);

            long long val = nums[j];
            best = std::max({best, val * pref_min, val * pref_max});
        }

        return best;
    }
};

class Solution {
    public long maxProduct(int[] nums, int m) {
        int n = nums.length;
        if (n < m) return 0;

        long prefMin = Long.MAX_VALUE;
        long prefMax = Long.MIN_VALUE;
        long best = Long.MIN_VALUE;

        for (int j = m - 1; j < n; j++) {
            int i = j - (m - 1);
            prefMin = Math.min(prefMin, nums[i]);
            prefMax = Math.max(prefMax, nums[i]);

            long val = nums[j];
            best = Math.max(best, Math.max(val * prefMin, val * prefMax));
        }

        return best;
    }
}

/**
 * @param {number[]} nums
 * @param {number} m
 * @return {number}
 */
var maxProduct = function(nums, m) {
    const n = nums.length;
    if (n < m) return 0;

    let prefMin = Infinity;
    let prefMax = -Infinity;
    let best = -Infinity;

    for (let j = m - 1; j < n; j++) {
        const i = j - (m - 1);
        if (nums[i] < prefMin) prefMin = nums[i];
        if (nums[i] > prefMax) prefMax = nums[i];

        const val = nums[j];
        const p1 = val * prefMin;
        const p2 = val * prefMax;
        if (p1 > best) best = p1;
        if (p2 > best) best = p2;
    }

    return best;
};
